independent.solution:
RULES = [
    {"name": "empty", "metric": "read", "op": "<", "threshold": 1, "severity": "critical"},
    {"name": "quarantine", "metric": "rate", "op": ">", "threshold": 0.05, "severity": "critical"},
    {"name": "slow", "metric": "seconds", "op": ">", "threshold": 120, "severity": "warning"},
]

def evaluate(metrics):
    out = []
    for r in RULES:
        value = metrics[r["metric"]]
        fired = value < r["threshold"] if r["op"] == "<" else value > r["threshold"]
        if fired:
            out.append(f"[{r['severity']}] {r['name']}: {value} {r['op']} {r['threshold']}")
    return out

for m in [{"read": 100, "rate": 0.02, "seconds": 60}, {"read": 100, "rate": 0.2, "seconds": 300}]:
    lines = evaluate(m)
    print("\n".join(lines) if lines else "no alerts")
